<?php declare(strict_types=1); namespace App\Core\Middleware; use App\Core\Csrf; use App\Core\Request; use App\Core\Response; final class CsrfMiddleware { public function handle(Request $request,\Closure $next):Response{if(in_array($request->method(),['POST','PUT','PATCH','DELETE'],true)){Csrf::verify($request->input('_csrf_token')??null);}return $next($request);} }